import random
from fractions import Fraction as F
random.seed(0)
def dot(a,b): return sum(x*y for x,y in zip(a,b))
def add(a,b): return tuple(x+y for x,y in zip(a,b))
def sub(a,b): return tuple(x-y for x,y in zip(a,b))
def mgda(a,b):
    d=sub(a,b)
    den=dot(d,d)
    if not den: return a
    t=max(F(0),min(F(1),-F(dot(b,d),den)))
    return tuple(t*x+(1-t)*y for x,y in zip(a,b))
for _ in range(200000):
    a=[tuple(random.randint(-3,3) for _ in range(2)) for _ in range(2)]
    b=[tuple(random.randint(-3,3) for _ in range(2)) for _ in range(2)]
    if any(dot(x,x)==0 for x in a+b): continue
    u,v=mgda(*a),mgda(*b)
    if dot(u,u)==0 or dot(v,v)==0: continue
    if any(dot(v,x)>0 for x in a) or any(dot(u,x)>0 for x in b): continue
    h=[add(x,y) for x,y in zip(a,b)]
    direct=mgda(*h)
    dec=add(u,v)
    gains=[dot(sub(dec,direct),x) for x in h]
    if min(gains)<0:
        print('Loss gradients:',a,'Flat gradients:',b)
